query MicrosoftMarketLanguageInventory20260914 {
 shop { id name myshopifyDomain currencyCode }
 shopLocales(published: true) { locale name primary published }
 markets(first: 50) { nodes {
  id name status type
  conditions { regionsCondition { regions(first: 50) { nodes { ... on MarketRegionCountry { id code name currency { currencyCode enabled } } } pageInfo { hasNextPage endCursor } } } }
  currencySettings { baseCurrency { currencyCode enabled } localCurrencies }
  webPresences(first: 50) { nodes { id rootUrls { locale url } } pageInfo { hasNextPage endCursor } }
 } pageInfo { hasNextPage endCursor } }
 webPresences(first: 50) { nodes { id defaultLocale { locale } alternateLocales { locale } rootUrls { locale url } markets(first: 50) { nodes { id name } pageInfo { hasNextPage endCursor } } } pageInfo { hasNextPage endCursor } }
}
